import { useEffect } from "react";
import { io, type Socket } from "socket.io-client";
import { useQueryClient } from "@tanstack/react-query";
import { tokenStore } from "@/lib/api";

export interface DriverBroadcastPayload {
  id?: string;
  type?: string;
  pickup_address?: string;
  drop_address?: string;
  price?: number | null;
  broadcast_expires_at?: string | null;
}

// The same retro landline ringer the Android app uses for ride alerts
// (generated by scripts/generate-retro-ring.mjs): two double-rings, 6 s.
let ringer: HTMLAudioElement | null = null;

function playRideAlertSound(): void {
  try {
    ringer ??= new Audio("/sounds/retro-ring.wav");
    ringer.currentTime = 0;
    // Browser autoplay policies may block it; vibration/visual alert still work.
    void ringer.play().catch(() => undefined);
  } catch {
    /* no audio support */
  }
}

export function alertDriverOfBroadcast(): void {
  if ("vibrate" in navigator) navigator.vibrate([220, 100, 220]);
  playRideAlertSound();
}

/**
 * One authenticated driver socket for the whole DriverShell. Polling remains
 * enabled as a reconciliation fallback for reconnects and missed events.
 */
export function useDriverBroadcastSocket(
  enabled: boolean,
  onBroadcast: (payload: DriverBroadcastPayload) => void,
): void {
  const queryClient = useQueryClient();

  useEffect(() => {
    if (!enabled || !tokenStore.access) return undefined;

    const socket: Socket = io("/driver", {
      auth: { token: tokenStore.access },
      transports: ["websocket", "polling"],
      autoConnect: true,
    });

    const handleBroadcast = (payload: DriverBroadcastPayload) => {
      // The server persists the RideOffer before emitting. Force an IMMEDIATE
      // refetch (not just invalidate) so two broadcasts arriving in the same
      // second each pull fresh offers — invalidate can coalesce them into one
      // refetch that races a 2nd ride's commit, making it look "missed" until
      // the next 8s poll. refetchType:'all' refetches even inactive observers.
      void queryClient.refetchQueries({ queryKey: ["driver", "offers"], type: "all" });
      onBroadcast(payload);
      alertDriverOfBroadcast();
    };

    // A ride that was offered is no longer available (cancelled / expired /
    // taken by someone else). Refetch offers so its card drops out of the list.
    const handleDismiss = () => {
      void queryClient.refetchQueries({ queryKey: ["driver", "offers"], type: "all" });
    };

    socket.on("ride:broadcast", handleBroadcast);
    socket.on("ride:dismiss", handleDismiss);
    return () => {
      socket.off("ride:broadcast", handleBroadcast);
      socket.off("ride:dismiss", handleDismiss);
      socket.disconnect();
    };
  }, [enabled, onBroadcast, queryClient]);
}
